/* Tiny WebAudio sound engine: no assets, mobile friendly. */
export class Sound {
  constructor() {
    this.ctx = null;
    this.enabled = true;
    this.crowdGain = null;
    this.crowdSource = null;
    this.master = null;
  }
  init() {
    if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume(); return; }
    try {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return;
      this.ctx = new AC();
      this.master = this.ctx.createGain();
      this.master.gain.value = this.enabled ? .55 : 0;
      this.master.connect(this.ctx.destination);
    } catch {}
  }
  setEnabled(v) {
    this.enabled = !!v;
    if (this.master) this.master.gain.setTargetAtTime(v ? .55 : 0, this.ctx.currentTime, .05);
  }
  tone(freq, dur=.12, type='sine', vol=.12, when=0, slide=0) {
    if (!this.ctx || !this.enabled) return;
    const t = this.ctx.currentTime + when;
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    o.type = type;
    o.frequency.setValueAtTime(freq, t);
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(30, freq + slide), t + dur);
    g.gain.setValueAtTime(0, t);
    g.gain.linearRampToValueAtTime(vol, t + .01);
    g.gain.exponentialRampToValueAtTime(.0001, t + dur);
    o.connect(g); g.connect(this.master);
    o.start(t); o.stop(t + dur + .02);
  }
  noise(dur=.15, vol=.1, low=900, when=0) {
    if (!this.ctx || !this.enabled) return;
    const t = this.ctx.currentTime + when;
    const len = Math.floor(this.ctx.sampleRate * dur);
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i=0;i<len;i++) data[i] = (Math.random()*2-1) * (1 - i/len);
    const src = this.ctx.createBufferSource(); src.buffer = buf;
    const filter = this.ctx.createBiquadFilter(); filter.type='lowpass'; filter.frequency.value=low;
    const g = this.ctx.createGain(); g.gain.value = vol;
    src.connect(filter); filter.connect(g); g.connect(this.master);
    src.start(t);
  }
  whistle() {
    if (!this.ctx || !this.enabled) return;
    this.tone(2100,.16,'sine',.06,0,180);
    this.tone(2600,.12,'sine',.035,.02,-250);
    this.noise(.05,.02,3000);
  }
  hit(dominant=false) {
    this.noise(dominant?.22:.14, dominant?.22:.13, dominant?300:480);
    this.tone(dominant?72:95,.13,'triangle',dominant?.2:.12,0,-30);
  }
  kick() {
    this.noise(.08,.09,1400);
    this.tone(170,.1,'triangle',.08,0,80);
  }
  cheer(level=1) {
    if (!this.ctx || !this.enabled) return;
    const dur = 1.1 * level;
    this.noise(dur, .13 * level, 1200);
    this.noise(dur*.8, .07*level, 2400, .1);
    [523,659,784].forEach((f,i)=>this.tone(f,.22,'sine',.018*level,i*.08));
  }
  crowd(on) {
    if (!this.ctx || !this.enabled) {
      if (this.crowdGain && this.ctx) this.crowdGain.gain.setTargetAtTime(0, this.ctx.currentTime, .2);
      return;
    }
    if (on) {
      if (this.crowdSource) {
        this.crowdGain.gain.setTargetAtTime(.055, this.ctx.currentTime, .5);
        return;
      }
      try {
        const len = this.ctx.sampleRate * 4;
        const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
        const d = buf.getChannelData(0);
        let last = 0;
        for (let i=0;i<len;i++) {
          const white = Math.random()*2-1;
          last = (last + .02 * white) / 1.02;
          d[i] = last * 3.2;
        }
        const src = this.ctx.createBufferSource(); src.buffer=buf; src.loop=true;
        const filter = this.ctx.createBiquadFilter(); filter.type='bandpass'; filter.frequency.value=700; filter.Q.value=.45;
        const g = this.ctx.createGain(); g.gain.value=0;
        src.connect(filter); filter.connect(g); g.connect(this.master); src.start();
        this.crowdSource=src; this.crowdGain=g;
        g.gain.setTargetAtTime(.05,this.ctx.currentTime,.8);
      } catch {}
    } else if (this.crowdGain) {
      this.crowdGain.gain.setTargetAtTime(0,this.ctx.currentTime,.25);
    }
  }
  anthem(teamId='en') {
    this.init();
    if (!this.ctx || !this.enabled) return;
    // A short, stately original fanfare rather than a copyrighted anthem.
    const melodies = {
      en:[392,523,659,587,523,392,440,523],
      nz:[440,554,659,880,659,554,440,392],
      za:[349,440,523,466,440,349,392,440],
      fr:[392,494,587,784,698,587,494,392],
      default:[392,523,659,523,440,523,659,784]
    };
    const notes = melodies[teamId] || melodies.default;
    notes.forEach((f,i)=>this.tone(f,.42,'triangle',.05,i*.34, i%2?10:-8));
    notes.slice(0,4).forEach((f,i)=>this.tone(f/2,.8,'sine',.03,i*.34));
    this.cheer(.4);
  }
}

:root{
  --bg:#06130e; --bg2:#081b13; --panel:#0b241a; --panel-2:#0f2f21; --panel-3:#133a29;
  --cream:#f4f0e3; --cream-2:#e6e3d5; --muted:#93aa9a; --muted-2:#6f8c79;
  --gold:#d9b45b; --gold-2:#f5df9d; --gold-3:#b98b35; --green:#64c98e; --green-2:#a7f0b9;
  --red:#e86e60; --blue:#86c8ed; --line:rgba(255,255,255,.085); --line-2:rgba(255,255,255,.14);
  --shadow:0 18px 60px rgba(0,0,0,.38); --radius:20px;
  --font-body:"Trebuchet MS","Segoe UI",system-ui,-apple-system,sans-serif;
  --font-head:"Arial Narrow","DejaVu Sans Condensed","Liberation Sans Narrow",Impact,sans-serif;
  --safe-b:env(safe-area-inset-bottom,0px); --safe-t:env(safe-area-inset-top,0px);
}
*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}
html,body{margin:0;min-height:100%;background:var(--bg);color:var(--cream);font-family:var(--font-body);overscroll-behavior-y:none}
body{min-height:100dvh;overflow-x:hidden}
body.modal-open{overflow:hidden}
button,input,select{font:inherit;color:inherit}
button{background:none;border:0;cursor:pointer;padding:0}
button:disabled{opacity:.4;cursor:not-allowed}
a{color:inherit}
::selection{background:var(--gold);color:#102018}
#app{min-height:100dvh;position:relative;isolation:isolate}
#ambient{position:fixed;inset:0;z-index:-1;background:
  radial-gradient(ellipse at 50% -10%,rgba(45,111,77,.28),transparent 60%),
  radial-gradient(ellipse at 90% 30%,rgba(217,180,91,.06),transparent 50%),
  linear-gradient(180deg,#071710,#040d09 80%)}
#ambient::after{content:"";position:absolute;inset:0;background-image:radial-gradient(rgba(255,255,255,.05) 1px,transparent 1px);background-size:7px 7px;opacity:.15;mask-image:linear-gradient(#000,transparent 70%)}
.screen{min-height:100dvh}
.page{min-height:100dvh;padding-bottom:calc(86px + var(--safe-b));animation:pageIn .35s ease both}
@keyframes pageIn{from{opacity:0;transform:translateY(5px)}to{opacity:1;transform:none}}
.ic{display:inline-block;vertical-align:middle;flex:none}
.hidden{display:none!important}
.muted{color:var(--muted)}
.kicker{display:inline-block;font-family:var(--font-head);font-size:10px;letter-spacing:.18em;text-transform:uppercase;color:var(--muted);font-weight:700}
.kicker.gold{color:var(--gold)}
.content-wrap{width:min(100%,980px);margin:0 auto;padding:0 18px}
.eyebrow{display:flex;align-items:center;gap:8px;font-family:var(--font-head);font-size:10px;letter-spacing:.18em;font-weight:700;color:var(--gold-2)}
.live-dot{width:6px;height:6px;border-radius:50%;background:var(--red);box-shadow:0 0 0 4px rgba(232,110,96,.14);animation:pulse 1.6s infinite}
@keyframes pulse{50%{box-shadow:0 0 0 7px rgba(232,110,96,.03)}}

/* ---------- Top bar ---------- */
.topbar{height:64px;padding:calc(8px + var(--safe-t)) 18px 8px;display:flex;align-items:center;justify-content:space-between;position:relative;z-index:5;max-width:1120px;margin:0 auto}
.brand{display:flex;align-items:center;gap:9px}
.brand-mark{width:34px;height:34px;border-radius:10px;background:linear-gradient(145deg,#1b563b,#0a2b1d);display:grid;place-items:center;color:var(--gold-2);border:1px solid rgba(217,180,91,.35);box-shadow:inset 0 1px rgba(255,255,255,.12),0 4px 14px rgba(0,0,0,.25)}
.brand-mark.lg{width:54px;height:54px;border-radius:16px}
.brand b{display:block;font-family:var(--font-head);font-size:14px;letter-spacing:.1em;line-height:1}
.brand span{display:block;font-size:8px;letter-spacing:.26em;color:var(--gold);margin-top:4px}
.top-actions{display:flex;gap:8px;align-items:center}
.icon-btn{width:38px;height:38px;border-radius:12px;display:grid;place-items:center;background:rgba(255,255,255,.055);border:1px solid var(--line);color:var(--cream);transition:.18s}
.icon-btn:hover{background:rgba(255,255,255,.1)}
.avatar{width:40px;height:40px;border-radius:13px;display:grid;place-items:center;background:rgba(255,255,255,.055);border:1px solid var(--line);overflow:hidden}

/* ---------- Crest ---------- */
.crest{--crest:48px;width:var(--crest);height:calc(var(--crest)*1.08);display:inline-grid;place-items:center;flex:none;filter:drop-shadow(0 3px 7px rgba(0,0,0,.35))}
.crest-inner{position:relative;width:100%;height:100%;background:linear-gradient(150deg,var(--c1) 0 56%,var(--c2) 56% 66%,var(--c1) 66%);clip-path:polygon(50% 0,94% 14%,88% 70%,50% 100%,12% 70%,6% 14%);display:grid;place-items:center;border:1px solid rgba(255,255,255,.15)}
.crest-inner:before{content:"";position:absolute;inset:4px;border:1px solid rgba(255,255,255,.28);clip-path:inherit;opacity:.7}
.crest-stripe{position:absolute;width:120%;height:4%;background:var(--c3);top:46%;left:-10%;transform:rotate(-8deg);opacity:.9}
.crest b{position:relative;font-family:var(--font-head);font-weight:900;font-size:calc(var(--crest)*.27);letter-spacing:.04em;color:#fff;text-shadow:0 1px 3px rgba(0,0,0,.7);z-index:1}
.crest[style*="--c1:#f4f2ea"] b,.crest[style*="--c1:#e9eef2"] b,.crest[style*="--c1:#f4f4f0"] b,.crest[style*="--c1:#f1c84b"] b,.crest[style*="--c1:#f2ce46"] b,.crest[style*="--c1:#7cb6e4"] b,.crest[style*="--c1:#5aa9dd"] b{color:#102018;text-shadow:0 1px rgba(255,255,255,.35)}

/* ---------- Buttons ---------- */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:46px;padding:0 18px;border-radius:14px;font-family:var(--font-head);font-size:13px;font-weight:800;letter-spacing:.07em;transition:transform .12s,filter .18s,background .18s;white-space:nowrap}
.btn:active{transform:scale(.97)}
.btn.gold{background:linear-gradient(160deg,var(--gold-2),var(--gold) 48%,var(--gold-3));color:#182216;box-shadow:0 8px 24px rgba(217,180,91,.18),inset 0 1px rgba(255,255,255,.6);border:1px solid rgba(255,242,190,.35)}
.btn.gold:hover{filter:brightness(1.06)}
.btn.glass{background:rgba(255,255,255,.07);border:1px solid var(--line-2);color:var(--cream);backdrop-filter:blur(10px)}
.btn.ghost{background:rgba(255,255,255,.035);border:1px solid var(--line);color:var(--cream-2)}
.btn.danger{background:rgba(232,110,96,.14);border:1px solid rgba(232,110,96,.35);color:#ffb4aa}
.btn.lg{min-height:52px;padding:0 22px;border-radius:15px}
.btn.xl{min-height:58px;font-size:15px;border-radius:17px;margin-top:8px}
.btn.full{width:100%;margin:10px 0}
.btn.sm{min-height:38px;padding:0 13px;font-size:11px;border-radius:11px}
.text-btn{display:inline-flex;align-items:center;gap:5px;font-family:var(--font-head);font-size:10px;letter-spacing:.12em;font-weight:800;color:var(--gold-2)}
.text-btn:hover{color:#fff}
.fine-print{text-align:center;font-size:10px;line-height:1.6;color:var(--muted-2);margin:14px 0 4px}
.section{margin-top:28px}
.section-head{display:flex;align-items:flex-end;justify-content:space-between;gap:12px;margin-bottom:14px}
.section-head h2{margin:3px 0 0;font-family:var(--font-head);font-size:25px;letter-spacing:-.01em;line-height:1}
.section-count{font-family:var(--font-head);font-size:12px;color:var(--muted-2);letter-spacing:.12em}

/* ---------- Hero ---------- */
.home-page{padding-bottom:calc(90px + var(--safe-b))}
.hero{position:relative;overflow:hidden;min-height:430px;margin:2px 10px 0;border-radius:24px;background:linear-gradient(115deg,#0c3021 0%,#092419 42%,#06160f 100%);border:1px solid rgba(255,255,255,.07);box-shadow:var(--shadow)}
.hero-lights{position:absolute;inset:0;background:
  radial-gradient(ellipse at 12% 0%,rgba(218,245,213,.18),transparent 38%),
  radial-gradient(ellipse at 82% 2%,rgba(255,231,164,.14),transparent 42%),
  linear-gradient(180deg,rgba(255,255,255,.04),transparent 40%)}
.hero-lights:after{content:"";position:absolute;left:-10%;right:-10%;top:0;height:100%;background:repeating-linear-gradient(102deg,transparent 0 70px,rgba(255,255,255,.018) 70px 71px)}
.hero-crowd{position:absolute;left:0;right:0;top:0;height:42%;background-image:radial-gradient(rgba(255,255,255,.22) .7px,transparent .8px),radial-gradient(rgba(217,180,91,.18) .7px,transparent .8px);background-size:6px 6px,11px 11px;background-position:0 0,3px 4px;opacity:.28;mask-image:linear-gradient(#000 0,transparent 90%)}
.hero-pitch{position:absolute;left:-22%;right:-22%;bottom:-5%;height:58%;transform:perspective(420px) rotateX(58deg);transform-origin:bottom;background:repeating-linear-gradient(90deg,rgba(71,147,100,.17) 0 42px,rgba(34,91,60,.12) 42px 84px);border-top:1px solid rgba(255,255,255,.12);opacity:.7}
.hero-pitch:after{content:"";position:absolute;inset:12% 18%;border:1px solid rgba(255,255,255,.18);border-radius:50% 50% 0 0;border-bottom:0}
.hero:after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(4,14,9,.7) 0%,rgba(4,14,9,.22) 58%,rgba(4,14,9,.45) 100%),linear-gradient(0deg,rgba(4,14,9,.7),transparent 40%);pointer-events:none}
.hero-copy{position:relative;z-index:3;padding:42px 20px 88px;max-width:78%}
.hero-copy h1{margin:12px 0 12px;font-family:var(--font-head);font-weight:900;font-size:clamp(50px,12vw,78px);line-height:.82;letter-spacing:-.045em;text-shadow:0 8px 30px rgba(0,0,0,.35)}
.hero-copy h1 span{display:inline-block;background:linear-gradient(180deg,#fff7d4 5%,#f0cf74 50%,#b9842d 100%);-webkit-background-clip:text;background-clip:text;color:transparent}
.hero-copy h1 em{font-style:normal;display:inline-block;color:transparent;-webkit-text-stroke:1.4px rgba(245,223,157,.8);font-size:.74em;transform:translateY(-2px);margin-left:3px}
.hero-copy p{font-size:12px;line-height:1.65;color:#b9cbbd;margin:0 0 18px;max-width:320px}
.hero-actions{display:flex;flex-wrap:wrap;gap:8px}
.hero-actions .btn{font-size:11px;padding:0 14px}
.hero-trophy{position:absolute;z-index:2;right:-12px;bottom:28px;width:190px;height:280px;display:flex;align-items:flex-end;justify-content:center;pointer-events:none;filter:drop-shadow(0 16px 28px rgba(0,0,0,.45))}
.hero-trophy .trophy-svg{width:100%;height:100%;position:relative;z-index:2;animation:trophyFloat 6s ease-in-out infinite}
.hero-trophy-glow{position:absolute;width:170px;height:170px;border-radius:50%;background:radial-gradient(rgba(255,225,144,.3),transparent 65%);filter:blur(16px);bottom:20%;z-index:1}
@keyframes trophyFloat{50%{transform:translateY(-7px) rotate(-1deg)}}
.hero-meta{position:absolute;z-index:3;left:20px;right:20px;bottom:18px;display:flex;gap:20px;border-top:1px solid rgba(255,255,255,.12);padding-top:11px}
.hero-meta span{font-family:var(--font-head);font-size:9px;letter-spacing:.14em;color:#9fb3a5;display:flex;align-items:baseline;gap:5px}
.hero-meta b{font-size:17px;color:var(--cream);letter-spacing:0}

/* ---------- Continue ---------- */
.continue-card{position:relative;margin:14px 0 0;background:linear-gradient(110deg,rgba(24,65,45,.9),rgba(10,32,22,.9));border:1px solid rgba(217,180,91,.2);border-radius:18px;padding:14px;overflow:hidden;cursor:pointer;transition:.2s}
.continue-card:hover{transform:translateY(-1px);border-color:rgba(217,180,91,.4)}
.continue-card.career{border-color:rgba(100,201,142,.18)}
.continue-badge{font-family:var(--font-head);font-size:8px;letter-spacing:.2em;color:var(--gold);margin-bottom:8px}
.continue-main{display:flex;align-items:center;gap:11px}
.continue-main h3{margin:0 0 3px;font-family:var(--font-head);font-size:17px;letter-spacing:0}
.continue-main p{margin:0;font-size:10px;color:var(--muted);line-height:1.4}
.continue-main>div:nth-child(2){flex:1;min-width:0}
.mini-crest{width:44px;height:44px;display:grid;place-items:center;flex:none}
.round-arrow{width:30px;height:30px;border-radius:50%;display:grid;place-items:center;background:rgba(255,255,255,.06);color:var(--gold-2)}
.continue-progress{height:3px;background:rgba(255,255,255,.07);border-radius:3px;margin-top:11px;overflow:hidden}
.continue-progress span{display:block;height:100%;background:linear-gradient(90deg,var(--gold-3),var(--gold-2));border-radius:3px}

/* ---------- Modes ---------- */
.mode-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}
.mode-card{position:relative;display:flex;align-items:center;gap:10px;min-height:76px;padding:12px;border-radius:16px;background:linear-gradient(150deg,rgba(255,255,255,.055),rgba(255,255,255,.018));border:1px solid var(--line);text-align:left;overflow:hidden;transition:.18s}
.mode-card:hover{background:rgba(255,255,255,.075);border-color:rgba(255,255,255,.16);transform:translateY(-1px)}
.mode-card:active{transform:scale(.985)}
.mode-icon{width:38px;height:38px;border-radius:12px;display:grid;place-items:center;background:rgba(100,201,142,.08);color:var(--green-2);border:1px solid rgba(100,201,142,.12);flex:none}
.mode-icon.gold-bg{background:rgba(217,180,91,.12);color:var(--gold-2);border-color:rgba(217,180,91,.2)}
.mode-text{display:flex;flex-direction:column;gap:2px;min-width:0}
.mode-text b{font-family:var(--font-head);font-size:14px;letter-spacing:.01em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mode-text small{font-size:9px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mode-large{grid-column:span 2;min-height:94px;background:linear-gradient(115deg,rgba(30,85,58,.8),rgba(12,40,27,.7));border-color:rgba(217,180,91,.25)}
.mode-large .mode-text b{font-size:18px}
.mode-tag{position:absolute;top:9px;right:9px;font-family:var(--font-head);font-size:7px;letter-spacing:.14em;color:var(--gold);background:rgba(217,180,91,.1);padding:3px 5px;border-radius:4px}
.mode-art{position:absolute;right:44px;top:-15px;width:74px;height:110px;opacity:.32;transform:rotate(9deg)}
.mode-art .trophy-svg{width:100%;height:100%}

/* ---------- Fixtures / spotlight ---------- */
.fixture-strip{display:flex;gap:8px;overflow-x:auto;scrollbar-width:none;padding-bottom:4px;margin:0 -18px;padding-left:18px;padding-right:18px}
.fixture-strip::-webkit-scrollbar{display:none}
.fixture-card{flex:0 0 190px;border:1px solid var(--line);border-radius:15px;padding:10px 11px;background:rgba(255,255,255,.035)}
.fixture-top{display:flex;justify-content:space-between;font-size:8px;letter-spacing:.1em;color:var(--muted);font-family:var(--font-head);margin-bottom:9px}
.fixture-top b{color:var(--gold-2)}
.fixture-teams{display:flex;align-items:center;justify-content:space-between;gap:5px}
.fixture-teams span{display:flex;flex-direction:column;align-items:center;gap:4px}
.fixture-teams b{font-family:var(--font-head);font-size:10px;letter-spacing:.08em}
.fixture-teams em{font-style:normal;font-family:var(--font-head);font-size:9px;color:var(--muted-2)}
.fixture-venue{font-size:8px;color:var(--muted-2);margin-top:8px;border-top:1px solid var(--line);padding-top:6px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.spotlight{position:relative;margin-top:28px;border-radius:20px;background:linear-gradient(115deg,#143e2b,#0b2419 70%);border:1px solid rgba(217,180,91,.18);overflow:hidden;padding:24px;display:flex;align-items:center;min-height:170px}
.spotlight-copy{position:relative;z-index:2;max-width:65%}
.spotlight-copy h2{margin:4px 0 5px;font-family:var(--font-head);font-size:32px;letter-spacing:-.02em}
.spotlight-copy p{margin:0 0 12px;font-size:11px;line-height:1.6;color:var(--muted)}
.spotlight-copy p b{color:var(--gold-2);font-size:16px}
.spotlight-crest{position:absolute;right:22px;top:50%;transform:translateY(-50%);width:130px;height:130px;display:grid;place-items:center}
.crest-ring{position:absolute;width:140px;height:140px;border:1px solid rgba(217,180,91,.2);border-radius:50%;animation:spin 24s linear infinite}
.crest-ring:after{content:"";position:absolute;width:5px;height:5px;background:var(--gold);border-radius:50%;top:-2px;left:50%}
@keyframes spin{to{transform:rotate(360deg)}}
.spotlight-lines{position:absolute;inset:0;background:repeating-linear-gradient(115deg,transparent 0 22px,rgba(255,255,255,.018) 22px 23px)}
.home-footer{display:flex;justify-content:space-between;gap:10px;font-size:8px;letter-spacing:.12em;color:var(--muted-2);font-family:var(--font-head);border-top:1px solid var(--line);margin-top:28px;padding:16px 0 4px}
.home-footer span{display:flex;align-items:center;gap:5px}

/* ---------- Bottom nav ---------- */
.bottom-nav{position:fixed;z-index:60;left:50%;bottom:calc(10px + var(--safe-b));transform:translateX(-50%);width:min(calc(100% - 20px),520px);height:62px;background:rgba(7,23,16,.92);border:1px solid rgba(255,255,255,.11);border-radius:20px;backdrop-filter:blur(18px);display:grid;grid-template-columns:repeat(4,1fr);box-shadow:0 12px 40px rgba(0,0,0,.4);transition:transform .25s,opacity .25s}
.bottom-nav.hidden{transform:translate(-50%,90px);opacity:0;pointer-events:none}
.nav-item{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;color:var(--muted-2);font-size:8px;letter-spacing:.05em;position:relative;transition:.18s}
.nav-item span{font-family:var(--font-head);font-weight:700}
.nav-item.active{color:var(--gold-2)}
.nav-item.active:before{content:"";position:absolute;top:6px;width:20px;height:2px;border-radius:2px;background:var(--gold)}
.nav-item:hover{color:var(--cream)}

/* ---------- Sub pages ---------- */
.sub-page{padding-bottom:calc(92px + var(--safe-b))}
.sub-header{position:sticky;top:0;z-index:30;display:grid;grid-template-columns:40px 1fr 40px;align-items:center;gap:12px;padding:calc(10px + var(--safe-t)) 16px 10px;background:linear-gradient(180deg,rgba(6,19,14,.96),rgba(6,19,14,.76) 70%,transparent);backdrop-filter:blur(12px);max-width:1000px;margin:0 auto}
.sub-header h1{margin:2px 0 0;font-family:var(--font-head);font-size:23px;letter-spacing:-.01em;line-height:1}
.sub-header .kicker{font-size:8px}

/* ---------- Settings ---------- */
.settings-panel{background:linear-gradient(160deg,rgba(255,255,255,.045),rgba(255,255,255,.015));border:1px solid var(--line);border-radius:18px;padding:5px 14px;margin:12px 0}
.settings-panel.flush{padding:0;border:0;background:none;margin:0}
.panel-title{font-family:var(--font-head);font-size:10px;letter-spacing:.18em;color:var(--gold);margin:13px 0 4px;padding:0 2px}
.panel-title.spaced{margin-top:22px}
.panel-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 0;border-bottom:1px solid var(--line)}
.panel-row:last-child{border-bottom:0}
.panel-row.column{display:block}
.panel-row label{display:block;font-family:var(--font-head);font-size:12px;font-weight:700;letter-spacing:.06em}
.panel-row small{display:block;font-size:9px;color:var(--muted);margin-top:3px}
.panel-row>div{min-width:0}
.row-between{display:flex;justify-content:space-between;align-items:center;gap:10px}
.row-between b{font-family:var(--font-head);font-size:12px;color:var(--gold-2)}
.toggle{width:44px;height:26px;border-radius:20px;background:rgba(255,255,255,.09);border:1px solid var(--line);position:relative;flex:none;transition:.2s}
.toggle span{position:absolute;width:20px;height:20px;border-radius:50%;background:#d7ded8;left:2px;top:2px;transition:.2s;box-shadow:0 1px 4px rgba(0,0,0,.4)}
.toggle.on{background:rgba(100,201,142,.3);border-color:rgba(100,201,142,.5)}
.toggle.on span{left:20px;background:var(--green-2)}
.segmented{display:flex;background:rgba(0,0,0,.22);border:1px solid var(--line);border-radius:10px;padding:2px;gap:2px;flex:none}
.segmented.wrap{flex-wrap:wrap;margin-top:9px}
.segmented button{padding:7px 9px;border-radius:8px;font-family:var(--font-head);font-size:9px;font-weight:700;letter-spacing:.06em;color:var(--muted)}
.segmented button.active{background:rgba(217,180,91,.15);color:var(--gold-2);box-shadow:inset 0 0 0 1px rgba(217,180,91,.2)}
.range{width:100%;margin:13px 0 4px;accent-color:var(--gold);height:4px}
.select{background:#0c261a;border:1px solid var(--line);border-radius:9px;padding:8px 9px;font-size:10px;max-width:190px;color:var(--cream)}
.text-input{width:100%;background:rgba(0,0,0,.24);border:1px solid var(--line-2);border-radius:12px;padding:13px 14px;font-size:14px;outline:none;margin:7px 0 8px}
.text-input:focus{border-color:rgba(217,180,91,.55)}
.field-label{display:block;font-family:var(--font-head);font-size:9px;letter-spacing:.16em;color:var(--muted);margin-top:16px}
.about-card{display:flex;gap:13px;align-items:flex-start;margin:16px 0;padding:16px;border-radius:16px;border:1px solid var(--line);background:rgba(255,255,255,.025)}
.about-card b{font-family:var(--font-head);font-size:13px;letter-spacing:.06em;display:block}
.about-card span{font-size:9px;color:var(--gold);display:block;margin:2px 0 6px}
.about-card p{font-size:9px;line-height:1.6;color:var(--muted);margin:0}

/* ---------- Quick match ---------- */
.versus-card{position:relative;display:grid;grid-template-columns:1fr 48px 1fr;align-items:center;gap:0;border-radius:20px;border:1px solid var(--line);overflow:hidden;background:linear-gradient(150deg,#123826,#081c13);margin-top:12px;padding:18px 0}
.versus-bg{position:absolute;inset:0;background:radial-gradient(ellipse at 50% 50%,rgba(217,180,91,.1),transparent 55%),repeating-linear-gradient(100deg,transparent 0 40px,rgba(255,255,255,.018) 40px 41px)}
.team-select{position:relative;z-index:2;display:flex;flex-direction:column;align-items:center;text-align:center;gap:4px;padding:0 8px}
.team-select h2{font-family:var(--font-head);font-size:15px;line-height:1.1;margin:5px 0 0;letter-spacing:-.01em}
.team-select p{font-size:8px;color:var(--muted);margin:0}
.pick-label{font-family:var(--font-head);font-size:7px;letter-spacing:.2em;color:var(--gold);position:absolute;top:-8px;left:50%;transform:translateX(-50%)}
.rating-pill{display:flex;align-items:center;gap:4px;font-family:var(--font-head);font-size:7px;letter-spacing:.08em;color:var(--muted);background:rgba(0,0,0,.2);border:1px solid var(--line);padding:4px 7px;border-radius:20px;margin-top:5px;white-space:nowrap}
.rating-pill b{font-size:12px;color:var(--gold-2)}
.rating-pill span{color:var(--green-2);font-size:7px}
.versus-mid{position:relative;z-index:2;display:flex;flex-direction:column;align-items:center;gap:2px}
.versus-mid span{font-family:var(--font-head);font-size:24px;font-weight:900;color:var(--gold);text-shadow:0 2px 8px rgba(0,0,0,.5)}
.versus-mid small{font-size:6px;letter-spacing:.13em;color:var(--muted-2)}
.swap-btn{position:absolute;z-index:3;left:50%;top:50%;transform:translate(-50%,-50%);width:34px;height:34px;border-radius:50%;background:#0e2b1e;border:1px solid rgba(217,180,91,.3);display:grid;place-items:center;color:var(--gold-2);box-shadow:0 4px 14px rgba(0,0,0,.3)}
.tap-hint{text-align:center;font-size:8px;color:var(--muted-2);margin:8px 0 16px;display:flex;align-items:center;justify-content:center;gap:4px}
.match-preview{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin:14px 0 6px}
.preview-stat{background:rgba(255,255,255,.03);border:1px solid var(--line);border-radius:11px;padding:9px;text-align:center}
.preview-stat span{display:block;font-family:var(--font-head);font-size:6px;letter-spacing:.12em;color:var(--muted-2);margin-bottom:5px}
.preview-stat b{font-family:var(--font-head);font-size:11px}
.form-dots{display:flex;justify-content:center;gap:2px}
.form-dots i{width:14px;height:14px;border-radius:4px;font-style:normal;font-size:7px;display:grid;place-items:center;font-weight:800}
.form-dots .win{background:rgba(100,201,142,.2);color:var(--green-2)}
.form-dots .loss{background:rgba(232,110,96,.15);color:#ffafa5}
.big-count{font-family:var(--font-head);font-size:18px;color:var(--gold-2)}

input.command:
cat >> styles.css <<'CSS'

/* ---------- Tournament ---------- */
.tournament-hero,.career-hero,.classic-hero,.custom-head,.training-hero{position:relative;overflow:hidden;border-radius:22px;border:1px solid var(--line);background:linear-gradient(145deg,#123c29,#081e14 70%);padding:30px 22px;margin-top:10px}
.tournament-hero{min-height:350px;display:flex;flex-direction:column;align-items:flex-start;justify-content:flex-end}
.tournament-hero h1,.career-hero h1,.classic-hero h1,.custom-head h1,.training-hero h1{margin:6px 0 10px;font-family:var(--font-head);font-weight:900;font-size:42px;line-height:.86;letter-spacing:-.035em;background:linear-gradient(180deg,#fff8d9,#e5c169 60%,#ac7a2c);-webkit-background-clip:text;background-clip:text;color:transparent}
.tournament-hero p,.career-hero p,.classic-hero p,.training-hero p{font-size:11px;line-height:1.7;color:#b6c8bb;max-width:430px;margin:0 0 12px;position:relative;z-index:2}
.tourney-glow{position:absolute;right:-20px;top:-50px;width:280px;height:280px;border-radius:50%;background:radial-gradient(rgba(217,180,91,.22),transparent 65%);filter:blur(20px)}
.tourney-trophy{position:absolute;right:8px;bottom:6px;width:165px;height:235px;opacity:.9;filter:drop-shadow(0 16px 30px rgba(0,0,0,.45))}
.tourney-trophy .trophy-svg{width:100%;height:100%}
.tourney-facts{display:flex;gap:18px;border-top:1px solid rgba(255,255,255,.1);padding-top:12px;width:100%;position:relative;z-index:2}
.tourney-facts span{display:flex;align-items:baseline;gap:5px;font-family:var(--font-head);font-size:7px;letter-spacing:.12em;color:var(--muted)}
.tourney-facts b{font-size:17px;color:var(--cream)}
.choose-nation{margin-top:20px}
.nation-pick{width:100%;display:flex;align-items:center;gap:13px;text-align:left;background:linear-gradient(120deg,rgba(255,255,255,.06),rgba(255,255,255,.018));border:1px solid var(--line);border-radius:18px;padding:15px;transition:.18s}
.nation-pick:hover{border-color:rgba(217,180,91,.3)}
.nation-info{flex:1;min-width:0}
.nation-info>span{font-family:var(--font-head);font-size:8px;letter-spacing:.15em;color:var(--gold)}
.nation-info h2{margin:1px 0 4px;font-family:var(--font-head);font-size:22px;line-height:1}
.nation-info p{margin:0;font-size:9px;color:var(--muted)}
.chev{color:var(--muted-2)}
.format-card{border:1px solid var(--line);border-radius:16px;background:rgba(255,255,255,.025);padding:4px 14px;margin:16px 0 4px}
.format-row{display:flex;gap:11px;padding:11px 0;border-bottom:1px solid var(--line)}
.format-row:last-child{border-bottom:0}
.format-icon{width:32px;height:32px;border-radius:9px;background:rgba(100,201,142,.08);color:var(--green-2);display:grid;place-items:center;flex:none}
.format-row b{font-family:var(--font-head);font-size:11px;letter-spacing:.03em}
.format-row p{margin:2px 0 0;font-size:9px;color:var(--muted);line-height:1.5}
.tourney-status{border-radius:18px;border:1px solid rgba(217,180,91,.18);background:linear-gradient(120deg,#143e2b,#0a2117);padding:15px;margin-top:12px}
.status-top{display:flex;align-items:center;justify-content:space-between;gap:10px}
.status-team{display:flex;align-items:center;gap:10px}
.status-team>div>span{font-family:var(--font-head);font-size:7px;letter-spacing:.15em;color:var(--gold)}
.status-team h2{font-family:var(--font-head);font-size:20px;margin:1px 0 0;line-height:1}
.status-stage{text-align:right}
.status-stage span{display:block;font-family:var(--font-head);font-size:7px;letter-spacing:.14em;color:var(--muted)}
.status-stage b{font-family:var(--font-head);font-size:10px;color:var(--gold-2);letter-spacing:.05em}
.tourney-progress{height:4px;border-radius:3px;background:rgba(0,0,0,.25);margin:13px 0 8px;overflow:hidden}
.tourney-progress span{display:block;height:100%;border-radius:3px;background:linear-gradient(90deg,var(--gold-3),var(--gold-2))}
.status-bottom{display:flex;justify-content:space-between;font-family:var(--font-head);font-size:7px;letter-spacing:.12em;color:var(--muted-2)}
.next-match{border:1px solid var(--line);border-radius:20px;background:linear-gradient(155deg,rgba(255,255,255,.06),rgba(255,255,255,.018));padding:15px;margin-top:13px;position:relative;overflow:hidden}
.next-match:before{content:"";position:absolute;inset:0;background:radial-gradient(ellipse at 50% 110%,rgba(217,180,91,.1),transparent 60%);pointer-events:none}
.next-label{position:relative;display:flex;align-items:center;gap:6px;font-family:var(--font-head);font-size:8px;letter-spacing:.12em;color:var(--gold-2);flex-wrap:wrap}
.next-label b{color:var(--muted);font-weight:400;margin-left:auto;font-size:7px}
.next-teams{position:relative;display:grid;grid-template-columns:1fr 42px 1fr;align-items:center;margin:16px 0}
.next-side{display:flex;flex-direction:column;align-items:center;gap:2px;position:relative;text-align:center}
.next-side h3{font-family:var(--font-head);font-size:26px;line-height:1;margin:5px 0 2px;letter-spacing:-.01em}
.next-side span{font-size:8px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:110px}
.next-side.mine h3{color:var(--gold-2)}
.next-side em{position:absolute;top:-3px;right:14px;font-style:normal;font-family:var(--font-head);font-size:6px;letter-spacing:.1em;background:var(--gold);color:#132018;padding:2px 4px;border-radius:3px;font-weight:800}
.next-v{display:flex;flex-direction:column;align-items:center;gap:2px}
.next-v span{font-family:var(--font-head);font-size:16px;color:var(--muted-2)}
.next-v small{font-family:var(--font-head);font-size:7px;letter-spacing:.1em;color:var(--gold)}
.next-actions{position:relative;display:grid;grid-template-columns:1.4fr 1fr;gap:7px}
.advance-card{display:flex;align-items:center;gap:12px;border:1px solid var(--line);border-radius:16px;background:rgba(255,255,255,.03);padding:14px;margin-top:13px}
.advance-icon{width:42px;height:42px;border-radius:12px;background:rgba(217,180,91,.1);color:var(--gold-2);display:grid;place-items:center;flex:none}
.advance-card>div:nth-child(2){flex:1}
.advance-card h3{font-family:var(--font-head);font-size:14px;margin:0 0 2px}
.advance-card p{font-size:9px;color:var(--muted);margin:0}
.tabs{display:flex;gap:3px;background:rgba(0,0,0,.2);border:1px solid var(--line);border-radius:12px;padding:3px;overflow-x:auto;scrollbar-width:none}
.tabs::-webkit-scrollbar{display:none}
.tabs button{flex:1;padding:9px 12px;border-radius:9px;font-family:var(--font-head);font-size:10px;font-weight:700;letter-spacing:.06em;color:var(--muted);white-space:nowrap}
.tabs button.active{background:rgba(217,180,91,.14);color:var(--gold-2);box-shadow:inset 0 0 0 1px rgba(217,180,91,.18)}
.pool-tabs{margin:12px 0 9px}
.table-wrap{overflow-x:auto;border:1px solid var(--line);border-radius:14px;background:rgba(255,255,255,.025);scrollbar-width:none}
.table-wrap::-webkit-scrollbar{display:none}
.standings-table{width:100%;border-collapse:collapse;min-width:330px;font-size:10px}
.standings-table th{padding:8px 6px;font-family:var(--font-head);font-size:7px;letter-spacing:.1em;color:var(--muted-2);font-weight:700;border-bottom:1px solid var(--line);text-align:center}
.standings-table th.left{text-align:left}
.standings-table td{padding:8px 6px;text-align:center;border-bottom:1px solid rgba(255,255,255,.045);color:var(--cream-2);font-variant-numeric:tabular-nums}
.standings-table tr:last-child td{border-bottom:0}
.standings-table tr.user-row{background:rgba(217,180,91,.075)}
.standings-table tr.qualify td:first-child{color:var(--green-2);font-weight:700}
.standings-table td.pts{font-family:var(--font-head);font-weight:800;font-size:12px;color:var(--gold-2)}
.tbl-team{display:flex;align-items:center;gap:6px;min-width:100px}
.tbl-team b{font-family:var(--font-head);font-size:10px;letter-spacing:.04em;width:28px}
.tbl-team span{font-size:8px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:90px}
.table-note{display:flex;align-items:center;gap:6px;font-size:8px;color:var(--muted-2);margin-top:7px;padding-left:3px}
.q-dot{width:5px;height:5px;border-radius:50%;background:var(--green)}
.fixture-list{border:1px solid var(--line);border-radius:14px;overflow:hidden;background:rgba(255,255,255,.02)}
.fixture-row{display:grid;grid-template-columns:1fr 56px 1fr;align-items:center;gap:4px;padding:9px 12px;border-bottom:1px solid var(--line);position:relative}
.fixture-row:last-child{border-bottom:0}
.fixture-row.mine{background:rgba(217,180,91,.055)}
.fx-team{display:flex;align-items:center;gap:5px;font-family:var(--font-head);font-size:10px}
.fx-team.away{justify-content:flex-end}
.fx-score{text-align:center;font-family:var(--font-head);font-size:10px;color:var(--muted);letter-spacing:.04em}
.fixture-row.played .fx-score{color:var(--cream)}
.fx-ft{position:absolute;right:4px;top:4px;font-family:var(--font-head);font-size:5px;letter-spacing:.1em;color:var(--muted-2)}
.bracket{display:flex;gap:8px;overflow-x:auto;padding-bottom:5px;scrollbar-width:none}
.bracket-col{flex:1;min-width:150px}
.bracket-col h4{font-family:var(--font-head);font-size:8px;letter-spacing:.13em;color:var(--gold);margin:0 0 7px}
.bracket-match{background:rgba(255,255,255,.03);border:1px solid var(--line);border-radius:10px;padding:5px;margin-bottom:6px}
.bracket-match.done{border-color:rgba(100,201,142,.18)}
.bm-team{display:flex;align-items:center;gap:5px;padding:4px 3px;font-family:var(--font-head);font-size:9px;border-bottom:1px solid rgba(255,255,255,.045)}
.bm-team:last-child{border-bottom:0}
.bm-team span{flex:1;color:var(--muted)}
.bm-team b{color:var(--cream)}
.bm-team.win span,.bm-team.win b{color:var(--gold-2)}
.bm-team .crest{--crest:20px}
.tbd-crest{width:20px;height:22px;border-radius:5px;background:rgba(255,255,255,.06);display:inline-block;text-align:center;font-size:8px;color:var(--muted)}
.bracket-empty{font-size:8px;color:var(--muted-2);border:1px dashed var(--line);border-radius:10px;padding:16px 6px;text-align:center}
.bracket-third{display:flex;align-items:center;gap:8px;margin-top:8px;font-family:var(--font-head);font-size:8px;color:var(--muted)}
.bracket-third span{color:var(--gold)}
.champion-card{position:relative;overflow:hidden;border-radius:22px;border:1px solid rgba(217,180,91,.3);background:linear-gradient(150deg,#1b4b33,#0b2318 70%);padding:28px 18px 20px;text-align:center;margin-top:13px}
.champion-card h1{font-family:var(--font-head);font-size:36px;line-height:.95;margin:4px 0 8px;background:linear-gradient(180deg,#fff8d9,#e5c169);-webkit-background-clip:text;background-clip:text;color:transparent}
.champion-card p{font-size:10px;color:var(--muted);max-width:340px;margin:0 auto 16px;line-height:1.6}
