.hist-modal-hero p{font-size:8px;line-height:1.55;color:var(--muted);margin:0;max-width:340px}
.hist-facts{display:grid;grid-template-columns:repeat(3,1fr);gap:5px;margin:8px 0}
.hist-facts>div{border:1px solid var(--line);border-radius:7px;padding:6px}
.hist-facts span{display:block;font-family:var(--font-head);font-size:5px;letter-spacing:.1em;color:var(--muted-2)}
.hist-facts b{display:block;font-family:var(--font-head);font-size:8px;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.hist-choose{display:flex;align-items:center;gap:8px;border:1px solid var(--line);border-radius:9px;padding:7px 9px;margin:9px 0}
.hist-choose>span{font-family:var(--font-head);font-size:6px;letter-spacing:.1em;color:var(--gold)}
.hist-choose>div{display:flex;align-items:center;gap:5px;flex:1}
.hist-choose b{font-family:var(--font-head);font-size:9px}
.trophy-modal-wrap{background:linear-gradient(160deg,#1a4731,#081c13)!important;border-color:rgba(217,180,91,.3)!important;text-align:center;overflow:hidden}
.trophy-modal{position:relative;text-align:center;padding:4px 0}
