.trophy-modal-art .trophy-svg{width:100%;height:100%}
.trophy-modal h2{font-family:var(--font-head);font-size:32px;margin:2px 0 3px;background:linear-gradient(180deg,#fff8d9,#e5c169);-webkit-background-clip:text;background-clip:text;color:transparent}
.trophy-modal>p{font-size:9px;color:var(--muted);margin:0 0 8px}
.toast{position:fixed;z-index:200;left:50%;bottom:calc(86px + var(--safe-b));transform:translate(-50%,20px);background:rgba(8,27,18,.96);border:1px solid rgba(217,180,91,.25);color:var(--cream);padding:10px 15px;border-radius:11px;font-size:10px;box-shadow:0 12px 30px rgba(0,0,0,.4);opacity:0;pointer-events:none;transition:.25s;max-width:calc(100% - 30px);display:flex;align-items:center;gap:7px;backdrop-filter:blur(10px)}
