.toast.success{border-color:rgba(100,201,142,.35)}
.toast.warn{border-color:rgba(232,110,96,.4)}
.toast-dot{width:6px;height:6px;border-radius:50%;background:var(--green-2);flex:none}
.empty-state{text-align:center;padding:80px 20px}
.empty-mark{width:64px;height:64px;border-radius:50%;background:rgba(217,180,91,.08);display:grid;place-items:center;margin:0 auto 12px;color:var(--gold)}
.empty-state h3{font-family:var(--font-head);font-size:22px;margin:0 0 5px}
.empty-state p{font-size:9px;color:var(--muted);max-width:280px;margin:0 auto 12px;line-height:1.6}
.rotate-hint{display:none}
