748:     away:{ team:meta.awayTeam, squad:awaySquad, lineupIds:meta.awayLineup, tactics:meta.awayTactics },
749:     userTeam:meta.userTeam||'home', halfSeconds:meta.halfSeconds||180,
750:     mode:meta.mode||'quick', trainingDrill:meta.trainingDrill||null,
751:     venue:meta.venue||meta.homeTeam.venue, difficulty:meta.difficulty||S.settings.difficulty,
752:     weather:meta.weather||'clear', onEvent:handleGameEvent
