466:           p.desiredX = ax; p.desiredY = ay;
467:         }
468:       } else {
469:         const d = this.aiDesire(p, dt);
470:         ax = d.x; ay = d.y; sprint = d.sprint;
471:       }
472:       if (this.kickoffPending) { ax = 0; ay = 0; }
473:       this.movePlayer(p, ax, ay, sprint, dt);
474:       this.separatePlayers(p);
475:       if (p.stamina < 35 && Math.random() < dt * .08) p.stun = .2;
476:     }
477:   }
478: 
479:   movePlayer(p, ax, ay, sprint, dt) {
480:     let l = Math.hypot(ax, ay);
481:     if (l > 1) { ax /= l; ay /= l; l = 1; }
482:     const staminaFactor = clamp(p.stamina/100, .55, 1);
483:     const maxSpd = p.speedNow * (sprint && p.stamina > 8 ? 1.22 : 1);
484:     const accel = 7.5 + (p.acceleration || 70) * .075;
485:     if (l > .08) {
486:       p.vx += ax * accel * dt;
487:       p.vy += ay * accel * dt;
488:       if (sprint && p.stamina > 8) p.stamina = Math.max(0, p.stamina - dt * (1.25 - (p.staminaAttr||p.stamina)*0.002));
489:       else p.stamina = Math.max(0, p.stamina - dt * .09);
490:     } else {
491:       p.vx *= Math.pow(.04, dt);
492:       p.vy *= Math.pow(.04, dt);
493:       p.stamina = Math.min(100, p.stamina + dt * (.32 + (p.staminaAttr||70)*.002));
494:     }
495:     const spd = Math.hypot(p.vx,p.vy);
496:     if (spd > maxSpd) { p.vx = p.vx/spd*maxSpd; p.vy = p.vy/spd*maxSpd; }
497:     // agility / balance affects turn sharpness
498:     p.x += p.vx * dt; p.y += p.vy * dt;
499:     const moved = Math.hypot(p.x-p.lastX,p.y-p.lastY);
500:     p.distanceRun += moved;
501:     if (this.ball.holder === p && moved > 0) p.metres += Math.max(0, (p.y - p.lastY) * p.dir);
502:     p.runCycle += moved * 2.1;
503:     p.lastX = p.x; p.lastY = p.y;
504:     p.x = clamp(p.x, -2, 72); p.y = clamp(p.y, -9, 109);
505:     if (p.stamina > 0) p.stamina = Math.min(100, p.stamina + dt * .01);
506:   }
507: 
508:   separatePlayers(p) {
509:     if (p.down > 0) return;
510:     for (const q of this.allPlayers) {
511:       if (q === p || !q.onField || q.down > 0 || q.card) continue;
512:       const dx = p.x-q.x, dy = p.y-q.y, d = Math.hypot(dx,dy), minD = p.radius+q.radius;
513:       if (d > .001 && d < minD) {
514:         const nx = dx/d, ny = dy/d, push = (minD-d);
515:         const total = p.mass+q.mass;
516:         p.x += nx*push*(q.mass/total); p.y += ny*push*(q.mass/total);
517:         q.x -= nx*push*(p.mass/total); q.y -= ny*push*(p.mass/total);
518:         if (this.ball.holder === p || this.ball.holder === q) {
519:           const carrier = this.ball.holder;
520:           const other = carrier === p ? q : p;
521:           const rel = Math.abs((carrier.vx-other.vx)*nx + (carrier.vy-other.vy)*ny);
522:           if (rel > 2.2) {
523:             carrier.vx *= .88; carrier.vy *= .88;
524:             other.vx -= nx * rel * .16; other.vy -= ny * rel * .16;
525:             if (Math.random() < .25) this.dust(carrier.x, carrier.y, 2, '#e5dcc4');
526:           }
527:         }
528:       }
529:     }
530:   }
531: 
532:   aiDesire(p, dt) {
533:     const carrier = this.ball.holder;
534:     const b = this.ball;
535:     const side = p.side;
536:     const dir = p.dir;
537:     const inPossession = carrier ? carrier.side === side : this.possession === side;
538:     p.think -= dt;
539:     if (this.kickoffPending) return { x:0, y:0, sprint:false };
540:     if (b.mode === 'kick' && b.z > .5) {
541:       // chase or cover
542:       if (b.lastKick === side) {
543:         const target = this.kickLanding();
544:         const d = Math.hypot(target.x-p.x, target.y-p.y);
545:         if (d < 25 && p.number >= 11) return { x:(target.x-p.x)/(d||1), y:(target.y-p.y)/(d||1), sprint:d>6 };
546:       } else if (p.number === 15) {
547:         const target = this.kickLanding();
548:         return { x:clamp((target.x-p.x)/12,-1,1), y:clamp((target.y-p.y)/12,-1,1), sprint:true };
549:       }
550:       return { x:0, y:0, sprint:false };
551:     }
552:     if (carrier === p) return this.aiCarrier(p, dt);
553:     if (inPossession) return this.aiSupport(p, dt);
554:     return this.aiDefend(p, dt);
555:   }
556: 
557:   aiCarrier(p, dt) {
558:     const dir = p.dir, b = this.ball;
559:     const opponents = this.opponentsOf(p).filter(o=>o.onField && o.down<=0 && !o.card);
560:     let nearest = null, nd = 999;
561:     for (const o of opponents) { const d = dist(p,o); if (d<nd) { nd=d; nearest=o; } }
562:     // try line
563:     const goalY = p.dir > 0 ? 100 : 0;
564:     const toGoal = Math.abs(goalY - p.y);
565:     const support = this.supportOptions(p);
566:     if (p.think <= 0) {
567:       p.think = rand(.22,.55);
568:       const kickBias = this.teamTactics(p.side).kick;
569:       const pressure = nd < 3.5;
570:       const inOwnHalf = (p.dir>0 ? p.y<50 : p.y>50);
571:       const losingLate = this.losingLate(p.side);
572:       const advantage = this.advantage?.team === p.side;
573:       if (!advantage && !losingLate && Math.random() < .012 + kickBias*.008 && this.phaseCount > 1) {
574:         if (inOwnHalf && nd < 4.5) { this.aiKick(p, 'box'); return { x:0,y:0,sprint:false }; }
575:         if (!inOwnHalf && Math.random()<.4) { this.aiKick(p, 'territory'); return { x:0,y:0,sprint:false }; }
576:       }
577:       if (pressure && support.length && Math.random() < .55 + (p.awareness||60)*.002) {
578:         this.aiPass(p, support[0]);
579:         return { x:0,y:0,sprint:false };
580:       }
581:       if (pressure && support.length && p.offloadWindow > 0 && Math.random() < .3) {
582:         this.aiPass(p, support[0], true);
583:         return { x:0,y:0,sprint:false };
584:       }
585:     }
586:     let tx = p.x, ty = p.y + dir * 3;
587:     if (nearest && nd < 7) {
588:       // find the widest gap
589:       const gaps = [-12,-7,-3,3,7,12].map(off => {
590:         const gx = clamp(p.x+off, 5, 65);
591:         const space = opponents.reduce((m,o)=>Math.min(m, Math.hypot(o.x-gx,o.y-(p.y+dir*5))), 99);
592:         return { gx, space };
593:       }).sort((a,b)=>b.space-a.space);
594:       tx = gaps[0].gx;
595:       ty = p.y + dir * 2.5;
596:       if (toGoal < 22) tx = lerp(p.x, 35, .12);
597:     }
598:     if (p.x < 7) tx = p.x + 6;
599:     if (p.x > 63) tx = p.x - 6;
600:     if (p.y*dir > 92) ty = p.y + dir*4;
601:     const dx = tx-p.x, dy = ty-p.y, d = Math.hypot(dx,dy)||1;
602:     return { x:dx/d, y:dy/d, sprint: nd>3 || toGoal<15 };
603:   }
604: 
605:   aiSupport(p, dt) {
606:     const b = this.ball, dir = p.dir, carrier = b.holder;
607:     if (!carrier) {
608:       const target = this.kickLanding();
609:       const d = Math.hypot(target.x-p.x,target.y-p.y);
610:       return { x:(target.x-p.x)/(d||1), y:(target.y-p.y)/(d||1), sprint:d<18 };
611:     }
612:     const attackDir = dir;
613:     const phase = this.phaseCount;
614:     let slotX, behind;
615:     if (p.number <= 8) {
616:       const forwardRank = p.number<=3 ? 1 : p.number<=5 ? 2 : 3;
617:       slotX = carrier.x + (p.number%2 ? -1:1) * (forwardRank*3 + (p.number%3));
618:       behind = 2 + forwardRank*2.2 + (phase>3?2:0);
619:     } else {
620:       const slots = {9:-2,10:-7,11:-25,12:-11,13:9,14:25,15:-17};
621:       slotX = carrier.x + (slots[p.number] || 0) * (p.x>35 ? -1 : 1);
622:       behind = p.number===9 ? 1.5 : p.number===10 ? 5 : 8 + (p.number%3)*2;
623:       if (phase > 2) behind += 2;
624:     }
625:     if (p.number === 9 && carrier !== p && this.phase !== 'open') behind = 1;
626:     let tx = clamp(slotX, 4, 66);
627:     let ty = carrier.y - attackDir * behind;
628:     // support line: run toward a gap ahead of carrier
629:     if (p.number>=11 && carrier.y*attackDir > 30) ty = carrier.y - attackDir * (p.number===15? 11 : 2.5);
630:     if (this.ball.holder && p.number >= 11 && carrier.y*attackDir > 55) ty = carrier.y + attackDir * 1.5;
631:     const dx = tx-p.x, dy = ty-p.y, d=Math.hypot(dx,dy)||1;
632:     const wantSprint = d > 9 && (p.number>=9);
633:     return { x:clamp(dx/d,-1,1), y:clamp(dy/d,-1,1), sprint:wantSprint };
634:   }
635: 
636:   aiDefend(p, dt) {
637:     const b = this.ball, dir = p.dir, carrier = b.holder;
638:     const attack = carrier ? carrier : { x:b.x, y:b.y };
639:     const lineY = attack.y - dir * (this.phase==='ruck'?1.2:4.2);
640:     const nearest = this.nearestDefenders(p.side, attack, 2);
641:     const isChaser = nearest.some(o=>o.id===p.id);
642:     if (p.number === 15) {
643:       const tx = clamp(lerp(35, attack.x, .7), 8, 62);
644:       const ty = clamp(attack.y - dir * 14, -5, 105);
645:       const dx=tx-p.x, dy=ty-p.y, d=Math.hypot(dx,dy)||1;
646:       return { x:dx/d*.9, y:dy/d*.9, sprint:d>10 };
647:     }
648:     if (isChaser && carrier) {
649:       const d = dist(p,attack);
650:       return { x:(attack.x-p.x)/(d||1), y:(attack.y-p.y)/(d||1), sprint:d<12 };
651:     }
652:     const slot = [0, -2, 2, -5, 5, -9, 9, 0, -1, -7, -24, -11, 8, 24, 0][p.number] || 0;
653:     const drift = clamp((attack.x-35)*.55, -8, 8);
654:     let tx = clamp(35 + slot*1.15 + drift, 3, 67);
655:     let ty = clamp(lineY - dir*(p.number%3)*.45, -5, 105);
656:     if (this.ball.mode==='kick' && b.z>0) {
657:       ty = clamp(attack.y - dir*7, -5, 105);
658:       tx = clamp(lerp(tx, b.x, .5), 3, 67);
659:     }
660:     if (p.number>=11 && p.number!==15) { tx = clamp(attack.x + (p.number===11?-22:22), 3, 67); }
661:     const dx=tx-p.x, dy=ty-p.y, d=Math.hypot(dx,dy)||1;
662:     return { x:clamp(dx/d,-1,1), y:clamp(dy/d,-1,1), sprint: d>9 && isChaser };
663:   }
664: 
665:   nearestDefenders(side, point, count=2) {
666:     return this[side].lineup.filter(p=>p.onField && p.down<=0 && !p.card)
667:       .map(p=>({p,d:dist(p,point)})).sort((a,b)=>a.d-b.d).slice(0,count).map(o=>o.p);
668:   }
669: 
670:   opponentsOf(p) { return this[p.side==='home'?'away':'home'].lineup; }
671: 
672:   teamTactics(side) {
673:     const team = this[side].team;
674:     const base = { expansive:.55, power:.5, flair:.5, structured:.5, kicking:.55, pace:.5, defense:.5, scrum:.5, balanced:.5, offload:.5 }[team.style] || .5;
675:     const t = this[side].tactics || {};
676:     return { kick: (t.kick ?? base) * .7 + .3, width: t.width ?? .5, offload: t.offload ?? base, lineSpeed: t.lineSpeed ?? .55 };
677:   }
678: 
679:   losingLate(side) {
680:     if (this.training) return false;
681:     const my = this.score[side], other = this.score[side==='home'?'away':'home'];
682:     return this.clock > 3300 && my < other;
683:   }
684: 
685:   supportOptions(p, count=4) {
686:     const dir = p.dir;
687:     return this[p.side].lineup.filter(q=>q!==p && q.onField && q.down<=0 && !q.card)
688:       .filter(q => (q.y - p.y) * dir < -0.3 && Math.abs(q.x-p.x) < 27 && Math.hypot(q.x-p.x,q.y-p.y) < 26)
689:       .map(q => {
690:         const opp = this.opponentsOf(q).filter(o=>o.onField&&o.down<=0).reduce((m,o)=>Math.min(m,dist(o,q)),99);
691:         const progress = (q.y - p.y)*dir;
692:         const score = opp*1.5 - Math.abs(q.x-p.x)*.12 - Math.max(0,-progress)*.1;
693:         return { q, score };
694:       }).sort((a,b)=>b.score-a.score).slice(0,count).map(o=>o.q);
695:   }
696: 
697:   aiPass(p, target, offload=false) {
698:     if (!target) return false;
699:     if (this.phase === 'kickoff') return false;
700:     const dir = p.dir;
701:     if ((target.y-p.y)*dir > .5) {
702:       this.forwardPass(p, target); return false;
703:     }
704:     const b = this.ball;
705:     b.holder = null;
706:     b.mode = 'pass';
707:     b.lastTouch = p.side;
708:     b.lastKick = null;
709:     b.pass = { targetId:target.id, fromX:p.x, fromY:p.y, toX:target.x, toY:target.y, t:0, duration:clamp(Math.hypot(target.x-p.x,target.y-p.y)/19,.18,.8), offload, passer:p.id, side:p.side };
710:     b.x = p.x; b.y = p.y; b.z = 1.3; b.vx = 0; b.vy = 0;
711:     p.passAnim = .35; p.passes++;
712:     this.stats[p.side].passes++;
713:     this.lastPasser = p.id;
714:     this.phaseCount++;
715:     if (offload) { p.offloads++; this.stats[p.side].offloads++; this.say(`${p.name} throws a one-handed offload!`, 'skill'); }
716:     this.emit('pass', { player:p.name, offload });
717:     return true;
718:   }
719: 
720:   aiKick(p, type) {
721:     if (!p || this.ball.holder !== p) return;
722:     const b = this.ball;
723:     const dir = p.dir;
724:     let angle = 0, power = 23, vz = 7;
725:     if (type === 'box') { angle = rand(-.18,.18); power = 17; vz = 10; }
726:     if (type === 'territory') { angle = rand(-.12,.12); power = 28; vz = 7; }
727:     if (type === 'grubber') { angle = rand(-.2,.2); power = 20; vz = 1.2; }
728:     if (type === 'bomb') { angle = rand(-.25,.25); power = 17; vz = 14; }
729:     if (type === 'cross') { angle = rand(-.5,.5); power = 20; vz = 8; }
730:     const vx = Math.sin(angle)*power;
731:     const vy = dir*Math.cos(angle)*power;
732:     b.holder = null; b.mode = 'kick'; b.x=p.x; b.y=p.y; b.z=1.2;
733:     b.vx=vx; b.vy=vy; b.vz=vz; b.lastKick=p.side; b.lastKickType=type; b.bounces=0;
734:     b.kickFrom = { x:p.x, y:p.y, side:p.side };
735:     p.kicks++; this.stats[p.side].kicks++;
736:     p.kickAnim=.5;
737:     this.say(`${p.name} ${type==='box'?'box-kicks':type==='grubber'?'sends a grubber through':type==='bomb'?'hoists a bomb':type==='cross'?'sends it cross-field':'kicks for territory'}.`, 'kick');
738:     this.emit('kick', { type, player:p.name });
739:   }
740: 
741:   kickLanding() {
742:     const b = this.ball;
743:     if (b.mode !== 'kick') return { x:b.x, y:b.y };
744:     let t = 0;
745:     let z = b.z, x = b.x, y = b.y;
746:     let vz = b.vz;
747:     while (z > 0 && t < 6) { t += .08; z += vz*.08; vz -= 9.81*.08; x += b.vx*.08; y += b.vy*.08; }
748:     return { x:clamp(x,0,70), y:clamp(y,-10,110) };
749:   }
750: 
751:   updateBall(dt) {
752:     const b = this.ball;
753:     if (b.mode === 'held' && b.holder) {
754:       const p = b.holder;
755:       b.x = p.x + Math.sin(this.animTime*4)*.05;
756:       b.y = p.y + p.dir*.45;
757:       b.z = .5;
758:       return;
759:     }
760:     if (b.mode === 'pass' && b.pass) {
761:       const pass = b.pass;
762:       pass.t += dt;
763:       const t = clamp(pass.t / pass.duration, 0, 1);
764:       b.x = lerp(pass.fromX, pass.toX, t);
765:       b.y = lerp(pass.fromY, pass.toY, t);
766:       b.z = 1.1 + Math.sin(t*Math.PI)*1.2;
767:       // interception
768:       for (const o of this[pass.side==='home'?'away':'home'].lineup) {
769:         if (!o.onField || o.down>0 || o.card) continue;
770:         if (Math.hypot(o.x-b.x,o.y-b.y) < 1.2 && Math.random() < .005 + (o.awareness||60)*.00008) {
771:           this.intercept(o); return;
772:         }
773:       }
774:       if (t >= 1) {
775:         const target = this.allPlayers.find(p=>p.id===pass.targetId);
776:         if (!target || !target.onField) { b.mode='loose'; b.z=0; this.knockOn(pass.side, 'Pass goes to ground'); return; }
777:         const pressure = this.opponentsOf(target).some(o=>o.onField && dist(o,target)<1.6);
778:         const catchChance = clamp(.97 - (100-(target.handling||70))*.003 - (pressure?.08:0), .72, .99);
779:         if (Math.random() > catchChance) {
780:           b.mode='loose'; b.z=.3; b.vx=rand(-2,2); b.vy=rand(-2,2);
781:           this.knockOn(pass.side, `${target.name} spills the pass!`);
782:         } else {
783:           b.mode='held'; b.holder=target; b.pass=null; b.z=.5;
784:           target.touches++;
785:           this.lastPasser = null;
786:           if (pass.offload) this.dust(target.x,target.y,2,'#e2d7bd');
787:         }
788:       }
789:       return;
790:     }
791:     if (b.mode === 'kick' || b.mode === 'loose') {
792:       b.x += b.vx*dt; b.y += b.vy*dt;
793:       if (b.mode === 'kick') {
794:         b.z += b.vz*dt; b.vz -= 9.81*dt;
795:         if (b.z <= 0) {
796:           b.z = 0;
797:           if (b.bounces < 2 && Math.abs(b.vz) > 1.5) { b.vz = Math.abs(b.vz)*.34; b.bounces++; this.dust(b.x,b.y,3,'#c9bd9e'); }
798:           else { b.vz = 0; b.mode='loose'; }
799:         }
800:       }
801:       if (b.mode === 'loose') {
802:         const fr = Math.pow(.55, dt);
803:         b.vx *= fr; b.vy *= fr;
804:         if (Math.hypot(b.vx,b.vy) < .4) { b.vx=0; b.vy=0; }
805:       }
806:       b.spin += Math.hypot(b.vx,b.vy)*dt*.4;
807:       this.checkCatch(dt);
808:     }
809:   }
810: 
811:   checkCatch(dt) {
812:     const b = this.ball;
813:     if (b.mode === 'held') return;
814:     if (b.mode === 'kick' && b.z > 2.2) return;
815:     let best=null, bd=99;
816:     for (const p of this.allPlayers) {
817:       if (!p.onField || p.down>0 || p.card) continue;
818:       const d = Math.hypot(p.x-b.x,p.y-b.y);
819:       if (d < 1.7 && d < bd) { bd=d; best=p; }
820:     }
821:     if (!best) return;
822:     const contest = this.opponentsOf(best).filter(o=>o.onField && Math.hypot(o.x-b.x,o.y-b.y)<2.2);
823:     const catchAttr = (best.handling||70) + (best.jumping||60)*.3 - contest.length*3;
824:     if (Math.random() < clamp(.45 + catchAttr*.005, .45,.95)) {
825:       b.holder = best; b.mode='held'; b.vx=0; b.vy=0; b.z=.5; b.pass=null;
826:       best.touches++;
827:       this.possession = best.side;
828:       if (b.lastKick && b.lastKick !== best.side) this.say(`${best.name} claims it safely for ${this[best.side].team.name}.`, 'info');
829:       this.emit('catch', { player:best.name });
830:     } else {
831:       b.vx += rand(-2,2); b.vy += rand(-2,2); b.z=.4;
832:       this.dust(b.x,b.y,3);
833:     }
834:   }
835: 
836:   checkTackles(dt) {
837:     if (this.phase !== 'open' && this.phase !== 'kickoff') return;
838:     const carrier = this.ball.holder;
839:     if (!carrier || carrier.down>0) return;
840:     for (const d of this.opponentsOf(carrier)) {
841:       if (!d.onField || d.down>0 || d.card || d.tackleCooldown>0) continue;
842:       const gap = dist(d,carrier);
843:       const userDef = d.id===this.controlledId && d.side===this.userTeam;
844:       const lunge = userDef && this.actionPressed;
845:       if (gap < (lunge?1.9:1.15)) {
846:         if (userDef && !this.actionPressed && gap>0.7) continue;
847:         this.resolveTackle(d, carrier);
848:         break;
849:       }
850:     }
851:   }
852: 
853:   resolveTackle(defender, carrier) {
854:     defender.tackleCooldown = .65;
