91:   const table=Object.fromEntries(ids.map(id=>({id,p:0,w:0,d:0,l:0,pf:0,pa:0,tf:0,ta:0,bonus:0,pts:0,form:[]}))
92:     .map(o=>[o.id,o]));
93:   for(const f of t.fixtures){
94:     if(f.stage!=='group'||f.group!==groupIndex||!f.played)continue;
95:     const h=table[f.homeId],a=table[f.awayId];
96:     if(!h||!a)continue;
97:     h.p++;a.p++;
98:     h.pf+=f.homeScore;a.pf+=f.awayScore;
99:     h.pa+=f.awayScore;a.pa+=f.homeScore;
100:     h.tf+=f.homeTries||0;a.tf+=f.awayTries||0;
101:     h.ta+=f.awayTries||0;a.ta+=f.homeTries||0;
102:     if(f.homeScore>f.awayScore){h.w++;a.l++;h.pts+=4;h.form.push('W');a.form.push('L');}
103:     else if(f.homeScore<f.awayScore){a.w++;h.l++;a.pts+=4;a.form.push('W');h.form.push('L');}
104:     else {h.d++;a.d++;h.pts+=2;a.pts+=2;h.form.push('D');a.form.push('D');}
105:     if((f.homeTries||0)>=4)h.bonus++;
106:     if((f.awayTries||0)>=4)a.bonus++;
107:     if(f.homeScore<f.awayScore&&f.awayScore-f.homeScore<=7)a.bonus++;
108:     if(f.awayScore<f.homeScore&&f.homeScore-f.awayScore<=7)h.bonus++;
109:   }
110:   return Object.values(table).map(o=>({...o,diff:o.pf-o.pa,pts:o.pts+o.bonus}))
111:     .sort((a,b)=>b.pts-a.pts||b.diff-a.diff||b.tf-a.tf||teamOf(a.id).rating-teamOf(b.id).rating);
