20:     const bandTeams=shuffle(sorted.slice(i,i+groupsCount));
21:     bandTeams.forEach((id,j)=>groups[(j+band)%groupsCount].push(id));
22:     band++;
23:   }
24:   // guarantee every group has the intended size where possible
25:   const all=[...groups.flat()];
26:   for (let i=0;i<groups.length;i++) {
27:     while (groups[i].length<Math.min(groupSize,Math.ceil(teamIds.length/groupsCount)) && all.length) {
28:       const candidate=all.find(id=>!groups[i].includes(id)&&groups.every(g=>g.length>=groups[i].length));
