58: function buildGroupFixtures(t) {
59:   const fixtures=[];
60:   t.groups.forEach((group,gi)=>{
61:     const list=[...group];
62:     if(list.length%2!==0) list.push('__bye__');
63:     const n=list.length;
64:     const rounds=n-1;
65:     for(let r=0;r<rounds;r++){
66:       for(let i=0;i<n/2;i++){
67:         const a=list[i],b=list[n-1-i];
68:         if(a==='__bye__'||b==='__bye__') continue;
69:         fixtures.push({
70:           id:uid(), stage:'group', group:gi, round:r+1,
71:           homeId: r%2===0?a:b, awayId: r%2===0?b:a,
72:           played:false, homeScore:null, awayScore:null, homeTries:null, awayTries:null,
73:           venue: STADIUMS[(gi*7+r*3)%STADIUMS.length], attendance: 45000+Math.floor(Math.random()*32000)
74:         });
75:       }
76:       // rotate
77:       list.splice(1,0,list.pop());
78:     }
79:     t.maxGroupRound=Math.max(t.maxGroupRound,rounds);
80:   });
81:   t.fixtures=fixtures;
82:   t.groupRound=1;
83: }
