31: function roundRobin(ids) {
32:   const list=[...ids];
33:   if(list.length%2)list.push('__bye__');
34:   const n=list.length,rounds=n-1,out=[];
35:   for(let r=0;r<rounds;r++){
36:     for(let i=0;i<n/2;i++){
37:       const a=list[i],b=list[n-1-i];
38:       if(a==='__bye__'||b==='__bye__')continue;
39:       out.push({round:r+1,home:r%2===0?a:b,away:r%2===0?b:a});
40:     }
41:     list.splice(1,0,list.pop());
42:   }
43:   return out;
44: }
