      <div class="custom-user-pick"><span>YOUR NATION</span><div>${crest(team(c.userTeam),38)}<b>${esc(team(c.userTeam).name)}</b></div><button class="text-btn" data-action="custom:user">CHANGE ${icon('swap',12)}</button></div>
