          </div>
          <p class="prematch-venue">${icon('globe',14)} ${esc(meta.venue||'World Rugby Stadium')} <span>•</span> ${icon('whistle',13)} ${meta.mode==='tournament'?'Cup match':meta.mode==='career'?'Series match':'International'}</p>
