  return `<span class="crest ${extra}" style="--c1:${c1};--c2:${c2};--c3:${c3};--crest:${size}px">
    <span class="crest-inner"><span class="crest-stripe"></span><b>${esc(t.abbr)}</b></span>
  </span>`;
}

