    c.beginPath();c.arc(0,-bodyR*.82,bodyR*.35,0,7);c.fill();
    c.fillStyle='#211a14';
    c.beginPath();c.arc(0,-bodyR*.94,bodyR*.34,Math.PI,0);c.fill();
    // number
    const textColor=this.isLight(jersey)?'#15241c':'#f7f4e9';
