  carrier.down = dominant ? 1.45 : .95;
  carrier.vx = defender.vx*.55 + (carrier.x-defender.x)*.2;
  carrier.vy = defender.vy*.55 + (carrier.y-defender.y)*.2;
  defender.vx *= .55; defender.vy *= .55;
