function webglAvailable() {
  try {
    const c=document.createElement('canvas');
    return !!(window.WebGLRenderingContext && (c.getContext('webgl2') || c.getContext('webgl')));
  } catch { return false; }
}

export class MatchRenderer {
  constructor(canvas, game, settings={}) {
    this.settings=settings; this.game=game;
    this.impl=null;
    if (webglAvailable()) {
      try { this.impl=new MatchRenderer3D(canvas,game,settings); }
      catch(err){ console.warn('3D renderer unavailable, using canvas', err); }
    }
    if (!this.impl) {
      const fresh=canvas.cloneNode(false);
      if (canvas.parentElement) canvas.replaceWith(fresh);
      this.canvas=fresh;
      this.impl=new CanvasMatchRenderer(fresh,game,settings);
    } else this.canvas=canvas;
    this.is3D=!!this.impl.is3D;
    const r=this.canvas.getBoundingClientRect();
    this._lastW=r.width; this._lastH=r.height;
  }
  resize(){ this.impl.resize(); }
  render(dt){ 
    const r=this.canvas.getBoundingClientRect();
    if (Math.abs(r.width-this._lastW)>1||Math.abs(r.height-this._lastH)>1){this._lastW=r.width;this._lastH=r.height;this.resize();}
    this.impl.render(dt);
  }
  dispose(){ this.impl.dispose?.(); }
}
