  const roof = this.material('#0b1813', { roughness: .9 });
  for (const side of [-1, 1]) {
    const x = side * 39.2;
    const shelter = new THREE.Mesh(new THREE.BoxGeometry(3.4, .3, 15), roof);
    shelter.position.set(x, 3.2, 0);
