content.text:
.sub-row small{display:block;font-size:7px;color:var(--muted);margin-top:2px}

/* ---------- Match ---------- */
.match-page{height:100dvh;max-width:1100px;margin:0 auto;display:flex;flex-direction:column;background:#04100a;position:relative;overflow:hidden}
.match-bar{flex:none;height:calc(58px + var(--safe-t));padding:calc(6px + var(--safe-t)) 8px 6px;display:grid;grid-template-columns:44px 1fr 44px;align-items:center;gap:2px;background:linear-gradient(180deg,#0b2419,#071a11);border-bottom:1px solid rgba(255,255,255,.07);position:relative;z-index:20}
.match-bar .icon-btn{width:34px;height:34px;border-radius:10px;background:rgba(255,255,255,.045)}
.scoreboard{display:flex;align-items:center;justify-content:center;gap:9px}
.sb-team{display:flex;align-items:center;gap:5px;min-width:70px}
.sb-team.home{justify-content:flex-end}
.sb-team.away{justify-content:flex-start}
.sb-team .crest{--crest:28px}
.sb-team b{font-family:var(--font-head);font-size:25px;line-height:1;font-variant-numeric:tabular-nums;min-width:18px;text-align:center}
.sb-name{font-family:var(--font-head);font-size:10px;letter-spacing:.08em;color:var(--muted);width:24px;text-align:center}
.sb-clock{text-align:center;min-width:64px}
.sb-clock span{display:block;font-family:var(--font-head);font-size:19px;font-weight:800;line-height:1;font-variant-numeric:tabular-nums;color:var(--cream)}
.sb-clock small{display:block;font-family:var(--font-head);font-size:6px;letter-spacing:.1em;color:var(--gold);margin-top:2px}
.sb-clock i{display:inline-block;width:4px;height:4px;border-radius:50%;background:var(--red);margin-top:2px;animation:pulse 1.4s infinite}
.field-wrap{flex:1;min-height:0;position:relative;overflow:hidden;background:#071a11}
#match-canvas{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none}
.field-topline{position:absolute;z-index:8;left:8px;right:8px;top:7px;display:flex;align-items:center;justify-content:space-between;gap:8px;pointer-events:none}
.live-pill{display:flex;align-items:center;gap:4px;font-family:var(--font-head);font-size:7px;letter-spacing:.1em;color:var(--cream);background:rgba(4,16,10,.7);border:1px solid rgba(255,255,255,.12);padding:4px 7px;border-radius:5px;backdrop-filter:blur(6px);white-space:nowrap;max-width:65%;overflow:hidden;text-overflow:ellipsis}
.live-pill i{width:4px;height:4px;border-radius:50%;background:var(--red);animation:pulse 1.2s infinite;flex:none}
.venue-line{font-size:7px;color:rgba(255,255,255,.55);background:rgba(4,16,10,.55);padding:4px 6px;border-radius:5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:44%}
.phase-banner{position:absolute;z-index:9;left:50%;top:38px;transform:translate(-50%,-6px);background:rgba(6,20,13,.86);border:1px solid rgba(217,180,91,.3);color:var(--gold-2);font-family:var(--font-head);font-size:9px;letter-spacing:.16em;padding:5px 10px;border-radius:5px;opacity:0;transition:.2s;pointer-events:none;white-space:nowrap}
.phase-banner.show{opacity:1;transform:translate(-50%,0)}
.possession-strip{position:absolute;z-index:8;left:0;right:0;top:0;height:3px;display:flex;pointer-events:none}
.poss-home{background:var(--gold);transition:width .4s}
.poss-away{background:#67a7d6;transition:width .4s}
.possession-strip em{position:absolute;left:50%;top:5px;transform:translateX(-50%);font-family:var(--font-head);font-size:5px;letter-spacing:.12em;color:rgba(255,255,255,.5);font-style:normal;background:rgba(4,16,10,.5);padding:1px 4px;border-radius:2px}
.commentary-ticker{position:absolute;z-index:8;left:8px;right:8px;bottom:8px;min-height:34px;display:flex;align-items:center;gap:6px;background:rgba(4,16,10,.82);border:1px solid rgba(255,255,255,.1);border-left:2px solid var(--gold);border-radius:6px;padding:5px 8px;backdrop-filter:blur(8px);pointer-events:none}
.commentary-ticker .ic{color:var(--gold);flex:none}
.commentary-ticker p{margin:0;font-size:8px;line-height:1.35;color:var(--cream-2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mini-radar{position:absolute;z-index:8;right:8px;top:34px;width:58px;height:78px;border-radius:6px;border:1px solid rgba(255,255,255,.14);overflow:hidden;background:rgba(4,16,10,.6);backdrop-filter:blur(4px);pointer-events:none}
.mini-radar canvas{width:100%;height:calc(100% - 9px);display:block}
.mini-radar span{display:block;text-align:center;font-family:var(--font-head);font-size:5px;letter-spacing:.12em;color:var(--muted-2);line-height:8px}
.context-panel{position:absolute;z-index:12;left:8px;right:8px;bottom:47px;display:none;pointer-events:none}
.context-panel.show{display:block}
.setpiece-card{background:rgba(5,20,13,.9);border:1px solid rgba(217,180,91,.28);border-radius:9px;padding:7px 9px;backdrop-filter:blur(8px);pointer-events:auto}
.sp-title{display:flex;align-items:center;gap:5px;font-family:var(--font-head);font-size:7px;letter-spacing:.1em;color:var(--gold-2)}
.timing-bar{position:relative;height:8px;border-radius:5px;background:rgba(255,255,255,.09);margin:6px 0 4px;overflow:hidden}
.good-zone{position:absolute;left:34%;width:38%;top:0;bottom:0;background:rgba(100,201,142,.35);border-left:1px solid rgba(167,240,185,.55);border-right:1px solid rgba(167,240,185,.55)}
.timing-bar i{position:absolute;top:-1px;width:3px;height:10px;background:var(--gold-2);box-shadow:0 0 5px rgba(255,227,154,.7);border-radius:2px}
.sp-sub{font-size:6px;color:var(--muted);letter-spacing:.02em}
.jumper-row{display:flex;gap:3px;margin:5px 0}
.jumper{flex:1;display:flex;justify-content:space-between;align-items:center;gap:2px;padding:5px 6px;border-radius:5px;border:1px solid var(--line);background:rgba(255,255,255,.04);font-family:var(--font-head);font-size:6px;letter-spacing:.06em;color:var(--muted)}
.jumper.active{border-color:rgba(217,180,91,.5);background:rgba(217,180,91,.14);color:var(--gold-2)}
.jumper small{font-size:5px;color:var(--muted-2)}
.tap-row{display:flex;align-items:center;gap:4px;margin:4px 0}
.tap-dot{width:7px;height:7px;border-radius:50%;background:rgba(255,255,255,.13)}
.tap-dot.on{background:var(--green-2);box-shadow:0 0 5px rgba(167,240,185,.5)}
.tap-row b{font-family:var(--font-head);font-size:6px;letter-spacing:.1em;color:var(--green-2);margin-left:auto}
.training-panel{position:absolute;z-index:9;left:8px;top:37px;width:128px;background:rgba(4,16,10,.78);border:1px solid rgba(255,255,255,.12);border-radius:7px;padding:6px 8px;backdrop-filter:blur(6px);pointer-events:none}
.training-panel b{display:block;font-family:var(--font-head);font-size:8px;margin:1px 0 4px}
.training-panel>span:last-child{font-family:var(--font-head);font-size:7px;color:var(--muted)}
.train-progress{height:3px;background:rgba(255,255,255,.1);border-radius:2px;overflow:hidden;margin-bottom:3px}
.train-progress i{display:block;height:100%;background:var(--gold);border-radius:2px}

/* Controls */
.control-deck{flex:none;height:calc(202px + var(--safe-b));padding:8px 10px calc(8px + var(--safe-b));display:grid;grid-template-columns:1fr 78px 1.12fr;align-items:center;gap:4px;background:linear-gradient(180deg,#071a11,#04110b);border-top:1px solid rgba(255,255,255,.08);position:relative;z-index:15;--ctrl:1}
.joystick-wrap{display:flex;flex-direction:column;align-items:center;gap:4px;justify-self:center}
.joystick{width:calc(104px * var(--ctrl));height:calc(104px * var(--ctrl));border-radius:50%;background:radial-gradient(circle at 50% 40%,rgba(255,255,255,.09),rgba(255,255,255,.025));border:1px solid rgba(255,255,255,.15);position:relative;touch-action:none;box-shadow:inset 0 0 24px rgba(0,0,0,.3),0 8px 24px rgba(0,0,0,.2)}
.joystick.active{border-color:rgba(217,180,91,.45);background:radial-gradient(circle at 50% 40%,rgba(217,180,91,.1),rgba(255,255,255,.025))}
.joy-cross{position:absolute;inset:22%;border-radius:50%;border:1px dashed rgba(255,255,255,.08)}
.joy-cross:before,.joy-cross:after{content:"";position:absolute;background:rgba(255,255,255,.07)}
.joy-cross:before{width:1px;height:120%;left:50%;top:-10%}
.joy-cross:after{height:1px;width:120%;top:50%;left:-10%}
.joy-thumb{position:absolute;width:42%;height:42%;left:29%;top:29%;border-radius:50%;background:linear-gradient(145deg,rgba(245,223,157,.95),rgba(185,139,53,.95));color:#1a2a1c;display:grid;place-items:center;box-shadow:0 5px 14px rgba(0,0,0,.35),inset 0 1px rgba(255,255,255,.6);transition:transform .05s}
.joy-thumb .ic{width:17px;height:17px;opacity:.8}
.joy-label{font-family:var(--font-head);font-size:6px;letter-spacing:.16em;color:var(--muted-2)}
.control-mid{display:flex;flex-direction:column;align-items:center;gap:6px;min-width:0}
.player-chip{text-align:center;background:rgba(255,255,255,.045);border:1px solid var(--line);border-radius:7px;padding:4px 5px;width:100%}
.player-chip span{display:block;font-family:var(--font-head);font-size:5px;letter-spacing:.06em;color:var(--gold);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.player-chip b{display:block;font-family:var(--font-head);font-size:9px;line-height:1.1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.stamina-chip{width:100%;text-align:center}
.stamina-chip span{font-family:var(--font-head);font-size:5px;letter-spacing:.08em;color:var(--muted-2)}
.stamina-bar{height:3px;background:rgba(255,255,255,.1);border-radius:2px;overflow:hidden;margin-top:2px}
.stamina-bar i{display:block;height:100%;background:linear-gradient(90deg,var(--gold),var(--green));border-radius:2px;transition:width .25s}
.tap-context{font-family:var(--font-head);font-size:5px;letter-spacing:.05em;color:var(--muted);text-align:center;line-height:1.2}
.action-pad{position:relative;width:calc(174px * var(--ctrl));height:calc(148px * var(--ctrl));justify-self:center}
.round-btn{position:absolute;border-radius:50%;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;font-family:var(--font-head);font-weight:800;letter-spacing:.04em;border:1px solid rgba(255,255,255,.2);box-shadow:0 7px 18px rgba(0,0,0,.35),inset 0 1px rgba(255,255,255,.25);transition:transform .08s,filter .15s;touch-action:manipulation}
.round-btn:active,.round-btn.held{transform:scale(.92);filter:brightness(1.15)}
.round-btn span{font-size:calc(6px * var(--ctrl));opacity:.9}
.round-btn.pass{width:calc(66px * var(--ctrl));height:calc(66px * var(--ctrl));right:0;top:0;background:linear-gradient(145deg,#f5df9d,#c89a41);color:#172216;border-color:rgba(255,246,200,.6)}
.round-btn.kick{width:calc(58px * var(--ctrl));height:calc(58px * var(--ctrl));left:0;top:13px;background:linear-gradient(145deg,#245b40,#123524);color:#c9f4d5;border-color:rgba(100,201,142,.35)}
.round-btn.action{width:calc(78px * var(--ctrl));height:calc(78px * var(--ctrl));right:11px;top:64px;background:linear-gradient(145deg,#a8493e,#632b26);color:#ffe3d9;border-color:rgba(232,110,96,.45)}
.round-btn.action.hot{background:linear-gradient(145deg,#c9a148,#7c5a20);color:#fff5d4;border-color:rgba(255,229,139,.65);animation:hotPulse 1s infinite}
@keyframes hotPulse{50%{box-shadow:0 0 0 7px rgba(217,180,91,.08),0 7px 18px rgba(0,0,0,.35)}}
.round-btn.sprint{width:calc(50px * var(--ctrl));height:calc(50px * var(--ctrl));left:8px;top:88px;background:linear-gradient(145deg,#2b4e69,#142c3d);color:#c7eaff;border-color:rgba(134,200,237,.35)}
.round-btn.disabled{opacity:.35;pointer-events:none}
.control-deck.lefty .joystick-wrap{order:3}
.control-deck.lefty .action-pad{order:1}
.control-deck.lefty .control-mid{order:2}

/* Match overlays */
.prematch-overlay{position:absolute;inset:0;z-index:40;background:linear-gradient(160deg,rgba(5,18,11,.94),rgba(4,13,8,.98));display:flex;align-items:center;justify-content:center;overflow:hidden;transition:opacity .45s,transform .45s}
.prematch-overlay.leaving{opacity:0;transform:scale(1.03);pointer-events:none}
.prematch-stadium{position:absolute;inset:0;background:
  radial-gradient(ellipse at 20% -5%,rgba(218,245,213,.16),transparent 40%),
  radial-gradient(ellipse at 80% -5%,rgba(255,231,164,.13),transparent 40%),
  repeating-linear-gradient(90deg,transparent 0 34px,rgba(255,255,255,.025) 34px 35px),
  linear-gradient(180deg,#0d3323,#06170f 70%)}
.prematch-stadium:after{content:"";position:absolute;left:-20%;right:-20%;bottom:-20%;height:55%;transform:perspective(380px) rotateX(62deg);background:repeating-linear-gradient(90deg,rgba(70,145,99,.18) 0 30px,rgba(35,91,60,.12) 30px 60px)}
.prematch-inner{position:relative;z-index:2;text-align:center;padding:18px;width:100%;max-width:520px}
.prematch-teams{display:grid;grid-template-columns:1fr 42px 1fr;align-items:center;gap:2px;margin:14px 0 8px}
.prematch-teams>div{display:flex;flex-direction:column;align-items:center;gap:3px}
.prematch-teams h2{font-family:var(--font-head);font-size:18px;line-height:1;margin:5px 0 0;letter-spacing:-.01em}
.prematch-teams span{font-size:8px;color:var(--muted)}
.prematch-v span{font-family:var(--font-head);font-size:20px;color:var(--gold)}
.prematch-v small{font-family:var(--font-head);font-size:5px;letter-spacing:.1em;color:var(--muted-2)}
.prematch-venue{display:flex;align-items:center;justify-content:center;gap:5px;font-size:8px;color:var(--muted);flex-wrap:wrap;margin:0 0 14px}
.prematch-actions{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin-top:8px}
.prematch-note{display:block;margin-top:11px;font-size:7px;color:var(--muted-2);letter-spacing:.04em}
.match-layer{position:absolute;inset:0;z-index:45;background:rgba(3,11,7,.8);backdrop-filter:blur(7px);display:flex;align-items:center;justify-content:center;padding:14px;animation:fadeIn .2s}
@keyframes fadeIn{from{opacity:0}to{opacity:1}}
.goal-card{width:min(100%,330px);background:linear-gradient(160deg,#123a27,#081d14);border:1px solid rgba(217,180,91,.3);border-radius:18px;padding:18px;text-align:center;box-shadow:0 20px 60px rgba(0,0,0,.5)}
.goal-card h2{font-family:var(--font-head);font-size:20px;margin:4px 0 3px}
.goal-card p{font-size:8px;color:var(--muted);margin:0 0 12px}
.goal-meter{position:relative;height:36px;border-radius:8px;background:linear-gradient(90deg,rgba(232,110,96,.16),rgba(100,201,142,.1) 34%,rgba(100,201,142,.1) 66%,rgba(232,110,96,.16));border:1px solid var(--line);overflow:hidden;margin:6px 0 3px}
.goal-zone{position:absolute;left:36%;width:28%;top:0;bottom:0;background:linear-gradient(180deg,rgba(245,223,157,.35),rgba(217,180,91,.12));border-left:1px solid rgba(245,223,157,.5);border-right:1px solid rgba(245,223,157,.5)}
.goal-marker{position:absolute;top:0;bottom:0;width:3px;background:#fff;box-shadow:0 0 10px #fff;left:50%;transform:translateX(-50%)}
.goal-post{position:absolute;width:2px;height:26px;background:rgba(255,255,255,.55);top:5px}
.goal-post.left{left:33%}.goal-post.right{left:66%}
.goal-scale{display:flex;justify-content:space-between;font-family:var(--font-head);font-size:5px;letter-spacing:.1em;color:var(--muted-2);margin-bottom:11px}
