  if (type==='grubber') { this.userKick(p,'grubber'); return; }
  if (type==='bomb') { this.userKick(p,'bomb'); return; }
  if (type==='touch') { this.userKick(p,'touch'); return; }
  this.userKick(p,'territory');
}

