aiDesire(p, dt) {
  const carrier = this.ball.holder;
  const b = this.ball;
  const side = p.side;
  const dir = p.dir;
  const inPossession = carrier ? carrier.side === side : this.possession === side;
  p.think -= dt;
  if (this.kickoffPending) return { x:0, y:0, sprint:false };
